import React, { useState } from 'react';
import './Navbar.css';
import logo from './Logo.jpg';
import { CiSearch } from "react-icons/ci";
import { HiMenu, HiX } from "react-icons/hi";

function Navbar({ setShow, searchTerm, setSearchTerm, products = [] }) {
    const [isMenuOpen, setIsMenuOpen] = useState(false);

    const toggleMenu = () => {
        setIsMenuOpen(!isMenuOpen);
    };

    const closeMenu = () => {
        setIsMenuOpen(false);
    };

   
    const handleScroll = (e, id) => {
        e.preventDefault();
        closeMenu();
        const targetElement = document.getElementById(id);
        if (targetElement) {
            targetElement.scrollIntoView({ behavior: 'smooth' });
        }
    };

    return (
        <div className='containet-navbar'>
            <div className="item-navbar">
                <img src={logo} alt="logo" className="navbar-logo" />
                
                <button className="hamburger-btn" onClick={toggleMenu} aria-label="Toggle Menu">
                    {isMenuOpen ? <HiX /> : <HiMenu />}
                </button>

                <div className={`nav-menu ${isMenuOpen ? 'active' : ''}`}>
                    <div className="Serach">
                        <CiSearch className="search-icon" />
                        <input
                            type='text'
                            placeholder='جستجو ...'
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>

                    <ul>
                        <li>
                            <a href="#Header" onClick={(e) => handleScroll(e, 'Header')}>
                                خانه
                            </a>
                        </li>
                        <li>
                            <a href="#category" onClick={(e) => handleScroll(e, 'category')}>
                                دسته‌بندی
                            </a>
                        </li>
                        <li>
                            <a href="#Products" onClick={(e) => handleScroll(e, 'Products')}>
                                محصولات
                            </a>
                        </li>
                        <li>
                            <a href="#footer" onClick={(e) => handleScroll(e, 'footer')}>
                                درباره ما
                            </a>
                        </li>
                        <li>
                            <a href="#!" onClick={(e) => { e.preventDefault(); setShow(true); closeMenu(); }}>
                                عضویت / ورود
                            </a>
                        </li>
                    </ul>
                </div>
            </div>
        </div>
    );
}

export default Navbar;